(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0031.js"] = [{"id":"glyph-seal-971e","script":"seal","character":"霞","reading":"xiá","description":"xiá：日出或日落时天空云层因受日光斜射而呈现的光彩朝（zhāo）～。晚～。彩～。云～。～帔。～光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霞"},{"id":"glyph-seal-972d","script":"seal","character":"霭","reading":"ǎi","description":"烟雾;蒸气\n姓氏。\n⒈云气云～。\n⒉气象上指轻雾。\n⒊［霭霭］云密集的样子暮云～～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霭"},{"id":"glyph-seal-9730","script":"seal","character":"霰","reading":"xiàn","description":"xiàn：在高空中的水蒸气遇到冷空气凝结成的小冰粒，多在下雪前或下雪时出现。\n〔～弹（dàn）〕炮弹的一种，内装黑色炸药和小铅球、钢球，弹头装有定时的引信，能在预定目标上空及附近爆炸。亦称榴霰弹”、子母弹”、群子弹”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霰"},{"id":"glyph-seal-9732","script":"seal","character":"露","reading":"lù；lòu","description":"lù：凝结在物体上的小水滴；显现，如露水、暴露。lòu：口语中指显现出来，如露头、露脸。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9738","script":"seal","character":"霸","reading":"bà","description":"bà：(1)指依杖权势或武力欺压他人的人或集团～王。称～。恶～。\n(2)奉行强力政策，或实行强力占有～占。～权。～道。～略。\n(3)古代称诸侯的盟主～主（ａ．中国春秋时势力最大并取得首领地位的诸侯；ｂ．在某一领域或地区称霸的人或集团）。～业。春秋五～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霸"},{"id":"glyph-seal-973e","script":"seal","character":"霾","reading":"mái","description":"mái：(1)空气中因悬浮着大量的烟、尘等微粒而形成的混浊形象阴～。\n(2)乱风时空中降下沙土，尘土飞扬。\n(3)古同埋”，埋葬。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霾"},{"id":"glyph-seal-9752","script":"seal","character":"青","reading":"qīng","description":"qīng：(1)深绿色或浅蓝色～绿。～碧。～草。～苔。～苗。～菜。～葱。～山绿水。～云直上。万古长～（喻高尚的精神或深厚的友情永远不衰）。\n(2)绿色的东西踏～。～黄不接。\n(3)靛蓝色靛～。～紫。～出于蓝，胜于蓝。\n(4)黑色～布。～线。～衫。～衣。\n(5)喻年轻～年。～春。～工。\n(6)竹简～简。～史（原指写在竹简上的记事，后指史书，如永垂～～”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-青"},{"id":"glyph-seal-9753","script":"seal","character":"靓","reading":"liàng；jing","description":"召见;邀请。也作请”\n妆饰艳丽\n淑静\n艳丽;美好\n幽静。通静”\n澹虖若深渊\n⒈〈方〉好看，漂亮～女孩。\n⒈装饰，打扮～装。\n⒉〈古〉通\"静\"。安静。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靓"},{"id":"glyph-seal-9756","script":"seal","character":"靖","reading":"jìng","description":"jìng：(1)平安，安静～冥（幽深闲静）。～默。\n(2)平定，使秩序安定绥～。～难（nàn）（平定叛乱）。\n(3)图谋，谋议实～夷我邦”。\n(4)恭敬士处～，敬老与贵，交不失礼。”\n(5)古同静”，静止。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靖"},{"id":"glyph-seal-9759","script":"seal","character":"静","reading":"jìng","description":"jìng：(1)停止的，与动”相对～止。～态。～物。平～。风平浪～。\n(2)没有声音安～。寂～。僻～。冷～。肃～。～悄悄。～穆。～谧。～默。～观。～听。\n(3)安详，闲雅～心。～坐。\n(4)古同净”，清洁。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-静"},{"id":"glyph-seal-975e","script":"seal","character":"非","reading":"fēi","description":"fēi：(1)不，不是～凡。～法。～分（fèn）。～礼。～但。～同小可。啼笑皆～。\n(2)不对，过失痛改前～。文过饰～。习～成是（对于某些错的事情习惯了，反认为是对的）。\n(3)与不”呼应，表示必须（有时后面没有不”字）我～看这本书。\n(4)责怪，反对～难（nàn）。～议。无可厚～。\n(5)指阿非利加洲”（位于东半球的西南部。简称非洲”）东～。西～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-非"},{"id":"glyph-seal-9760","script":"seal","character":"靠","reading":"kào","description":"kào：(1)倚着，挨近倚～。～垫。～背。船～岸。\n(2)依赖依～。～托。～头。\n(3)信托可～。～得住。牢～。\n(4)传统戏剧中武将所穿的铠甲扎～。～旗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靠"},{"id":"glyph-seal-9761","script":"seal","character":"靡","reading":"mí","description":"mí：(1)浪费，奢侈～荡。～费。侈～。\n(2)分散～散（消灭）。\n(3)古同糜”，糜烂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靡"},{"id":"glyph-seal-9762","script":"seal","character":"面","reading":"miàn","description":"⒈脸，头的前部～孔。颜～。～不改色。\n⒉直接接触，当着本人在场～谈。当～说。\n⒊朝着，脸对着～向。～山而居。\n⒋部位，方向前～。里～。右～。四～八方。～ ～俱到。\n⒌东西的外表地～。鞋～子。被盖～儿。\n⒍几何学上指线移动所生成的形迹，有长有宽没有厚～积。平～。\n⒎量词三～旗帜。两～镜子。\n①脸面，面子没有～目见人。\n②相貌，脸的形状～目可憎。\n③〈喻〉事物的景象状态～目一新。\n①体面怕丢～子。\n②情面秉公执法，不讲～子。\n③东西的外表桌～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-面"},{"id":"glyph-seal-9765","script":"seal","character":"靥","reading":"yè","description":"妇女面颊上所涂的妆饰\n靥yǎn 1.黑痣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靥"},{"id":"glyph-seal-9769","script":"seal","character":"革","reading":"gé","description":"gé：(1)去了毛经过加工的兽皮皮～。～履（皮鞋）。～囊。\n(2)改变～新。～命（ａ．原意是改变命运；ｂ．现指改变社会制度、建立新社会的群众运动；ｃ．亦指改造旧技术、旧思想的运动）。改～。变～。\n(3)取消，除掉～除。～职。～故鼎新（去除旧的，建立新的）。\n(4)中国古代乐器八音之一，如鼓等。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-革"},{"id":"glyph-seal-9773","script":"seal","character":"靳","reading":"jìn","description":"jìn：(1)吝惜，不肯给予～秘（吝惜而不外传）。\n(2)戏辱，奚落。\n(3)古代套在辕马胸前的皮革，因用作夹辕两马的代称。\n(4)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靳"},{"id":"glyph-seal-9776","script":"seal","character":"靶","reading":"bǎ","description":"bǎ：(1)练习射箭或射击用的目标～子。～场。～标。打～。\n(2)缰绳。\n(3)供加速器、原子核反应堆、放射性源等发出的粒子流轰击的实物样品，用以研究核反应，获得放射性同位素或产生Ｘ射线等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靶"},{"id":"glyph-seal-9778","script":"seal","character":"靸","reading":"sǎ","description":"靸sǎ〈方〉\n⒈将鞋后帮踩在脚跟下～着鞋。又指穿拖鞋。\n①草制的一种拖鞋。\n②鞋帮纳得很密，前面有皮梁或皮脸的鞋。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靸"},{"id":"glyph-seal-977c","script":"seal","character":"靼","reading":"dá","description":"dá：柔软的皮革。\n〔鞑～〕见鞑”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靼"},{"id":"glyph-seal-9785","script":"seal","character":"鞅","reading":"yāng；yàng","description":"yāng：古代用马拉车时套在马颈上的皮套子。\nyàng：〔牛～〕牛拉东西时架在脖子上的器具。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞅"},{"id":"glyph-seal-978b","script":"seal","character":"鞋","reading":"xié","description":"xié：穿在脚上便于走路的东西皮～。～袜。～帮。～面。～底。～油。～匠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞋"},{"id":"glyph-seal-978d","script":"seal","character":"鞍","reading":"ān","description":"ān：套在骡马背上便于骑坐的东西马～。～鞒。～韂（chàn）（马鞍和垫在马鞍下面的东西。亦称鞍鞯”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞍"},{"id":"glyph-seal-9798","script":"seal","character":"鞘","reading":"qiào；shāo","description":"qiào：装刀、剑的套子刀～。剑～。\nshāo：拴在鞭子末端的细皮条鞭～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞘"},{"id":"glyph-seal-97a0","script":"seal","character":"鞠","reading":"jū；jv","description":"jū：(1)养育，抚养～育。～养。\n(2)弯曲～躬。～躬尽瘁。\n(3)大，穷极～凶。\n(4)幼小～子（稚子）。\n(5)穷困尔惟～自苦”。\n(6)告诫陈师～旅”。\n(7)古代的一种皮球蹴～。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞠"},{"id":"glyph-seal-97a3","script":"seal","character":"鞣","reading":"róu","description":"róu：制造皮革时，用栲胶、鱼油等使兽皮柔软～制。～皮子。\n〔～酸〕有机化合物，淡黄色粉末，有微臭。工业上用来制墨水和鞣皮革，可入药。亦称单宁”、单宁酸”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞣"},{"id":"glyph-seal-97ac","script":"seal","character":"鞬","reading":"jiān","description":"古代装弓箭的器具。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-97ad","script":"seal","character":"鞭","reading":"biān","description":"biān：(1)驱使牲畜的用具，柔软像绳子～杆。～长莫及。\n(2)用鞭子抽打～打。～扑。～责。～策。\n(3)形状细长类似鞭子的东西教～。\n(4)一种古代兵器，铁制有节，无锋刃钢～。竹节～。\n(5)编连成串的爆竹～炮。小～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞭"},{"id":"glyph-seal-97af","script":"seal","character":"鞯","reading":"jiān","description":"衬托马鞍的垫子","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞯"},{"id":"glyph-seal-97b2","script":"seal","character":"鞲","reading":"gōu","description":"gōu：〔～鞴〕活塞，唧筒里或蒸气机、内燃机的气缸里往复运动的机件，作用是把蒸气或燃料爆发的压力变成机械能。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞲"},{"id":"glyph-seal-97b4","script":"seal","character":"鞴","reading":"bèi","description":"bèi：(1)把鞍辔等套在马身上。\n(2)古代的鼓风吹火器。\n〔鞲～〕见鞲”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞴"},{"id":"glyph-seal-97e6","script":"seal","character":"韦","reading":"wéi","description":"韦 〈名>\n熟皮,去毛熟治的皮革","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韦"},{"id":"glyph-seal-97e7","script":"seal","character":"韧","reading":"rèn","description":"韧劲,韧劲儿","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韧"},{"id":"glyph-seal-97ea","script":"seal","character":"韪","reading":"wěi","description":"美好","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韪"},{"id":"glyph-seal-97ec","script":"seal","character":"韬","reading":"tāo","description":"装弓的袋子\n用兵的计谋\n韬 〈动〉\n掩藏\n⒈盛弓或剑的套子。\n⒉容纳有～世之量。\n⒊遮掩，隐蔽～面。～迹。～晦。\n⒋用兵的谋略太公～。\n韬tào 1.古代护臂的皮套。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韬"},{"id":"glyph-seal-97ed","script":"seal","character":"韭","reading":"jiǔ","description":"jiǔ：〔～菜〕多年生草本植物，叶细长而扁，夏秋间开凶花；叶和花嫩时可食，种子可入药。简称韭”，如～黄”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韭"},{"id":"glyph-seal-97f3","script":"seal","character":"音","reading":"yīn","description":"yīn：(1)声，亦特指有节奏的声声～。～乐（yuè）。～律。～色。～量。～区。～韵。～像。～容（声音、容貌）。弦外之～。\n(2)信息，消息～信。佳～。～讯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-音"},{"id":"glyph-seal-97f5","script":"seal","character":"韵","reading":"yùn","description":"yùn：(1)汉语字音中的元音或元音加收尾音，即声母以外的部分，或声母和介音以外的部分，称韵母”。如ｔ幔睿绲脑夏甘轻ｎｇ”，ｈｕ幔睿绲脑夏甘牵踽ｎｇ”～文（有韵律节奏的文学体裁，亦指用这种体裁写成的文章，包括诗、词、歌、赋等。区别于散文”）。押～。～腹（韵母中主要元音）。～脚（韵文句末押韵的字）。～律（诗词中的平仄格式和押韵的规则）。\n(2)和谐而有节奏的～白。琴～悠扬。\n(3)风度，风致，情趣，意味风～。气～。～味。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韵"},{"id":"glyph-seal-97f6","script":"seal","character":"韶","reading":"sháo","description":"sháo：(1)古代乐曲名。\n(2)美～光（ａ．美丽的春光；ｂ．喻美好的青年时代）。～华（同韶光”）。～景（美丽的春光）。～秀（清秀）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韶"},{"id":"glyph-seal-9875","script":"seal","character":"页","reading":"yè","description":"书页\n量词\n一般指两面印刷的书籍、杂志、资料等印刷品的一张纸的一面。如一本三百页的书;第一页\n也指书籍、杂志、报纸、信件或类似物件的一张纸。如撕下其中的一页\n⒉量词。\n页xié 1.头。脑袋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-页"},{"id":"glyph-seal-9876","script":"seal","character":"顶","reading":"dǐng","description":"①人体或物体的最高部分头～、屋～。\n②用头支承～碗。\n③自下而上用力拱起幼芽～出土。\n④用头撞击被羊～了一个跟头。\n⑤顶撞。\n⑥对面迎着～风。\n⑦支撑；抵住～门杠、～住敌人多次进犯。\n⑧相当一人～两人用。\n⑨顶替～名。\n【顶点】\n①最高点；极点。\n②〈数〉三角形中顶角的两条边的交点或锥体的尖顶。\n【顶端优势】〈生〉植物的顶芽抑制侧芽生长的现象。农业上常用消除或维持顶端优势的办法控制作物、果树和花木的生长，以利增产和控制花木株形的目的。\n【顶技】一种杂技。表演者用身体一些部位顶直棍棒，或在棍棒顶端放置易碎物品而保持平衡使其不落地。\n【顶天立地】形容豪迈正大的英雄气概。\n【顶细胞】指被子植物二细胞原胚时期上部的一个细胞。\n【顶芽】位于茎的主轴或侧枝顶端的芽。单轴分枝树木主轴的顶芽生长旺盛，有的顶芽可形成花芽，如苹果、梨等。\n【顶真】〈语〉修辞学上辞格之一。用前文结尾的词语或词组做下文的起头，使语句递接紧凑而生动畅达。如'茵茵牧草绿山坡，山坡畜群似云朵，云朵游动笛声起，笛声悠扬\n卷浪波。'\n【顶珠】〈语〉见【顶真】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顶"},{"id":"glyph-seal-9877","script":"seal","character":"顷","reading":"qǐng","description":"通倾”。倾斜;偏侧\n頃顷\n田地面积的单位,等于一百亩\n⒈地积单位。1百市亩＝1市～＝6.6667公～。\n⒉时间短，跟\"久\"相对～刻。俄～。有～。少～。\n⒊刚才～闻。～接家书。\n⒋〈古〉通\"倾\"。侧，斜～耳。\n顷qīng 1.同\"倾\"。头不正。 2.同\"倾\"。倾斜;偏侧。 3.同\"倾\"。倾注。 4.同\"倾\"。倾覆。 5.同\"倾\"。古指妇人专擅国政。谓不正规，非正统。 6.姓『代有顷宪","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顷"},{"id":"glyph-seal-9879","script":"seal","character":"项","reading":"xiàng","description":"泛指人颈\n代数中不用加、减号连接的单式\n款项\n⒈颈子的后部。泛指颈部～背。屈～。引～高歌。\n⒉事物的分类或条目事～。～目。八～注意。\n⒊钱，经费款～。收入～。\n⒋量词两～任务。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-项"},{"id":"glyph-seal-987a","script":"seal","character":"顺","reading":"shùn","description":"顺从;顺应\n⒈向着同一个方向，跟\"逆\"相对～水。～应。～风而呼。～于民心。\n⒉沿，循，依次～大路走。因雨～延。～次前进。\n⒊随，趁便～便。～手关电。～口而出。\n⒋整理，使有条理理～头发。这篇文章，还要～一～。\n⒌适合，符合心意～眼。～心。～意。\n⒍服从～从。～着。\n⒎匀和风调雨～。\n⒏道理通达，符合事理～理。名正言～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顺"},{"id":"glyph-seal-987b","script":"seal","character":"须","reading":"xū","description":"野兽的魀。泛指动、\n①须要务～注意、必～努力。\n②姓。\n⒉等待；等到。\n①原来指长在下巴上的胡子，后来泛指胡须～发、～眉。\n②须子触～、花～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-须"},{"id":"glyph-seal-987c","script":"seal","character":"顼","reading":"xū","description":"用于“颛顼”，传说中的上古帝王名。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-987d","script":"seal","character":"顽","reading":"wán","description":"愚顽之人;顽固派\n凶恶的人\n引申为浑圆\n顽固,不驯服\n⒈愚蠢无知愚～。痴～。笨～。\n⒉固执，守旧～固。～梗。\n⒊淘气～皮。～童。\n⒋〈古〉凶暴，贪婪～贪。\n⒌通\"玩\"。游戏，耍弄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顽"},{"id":"glyph-seal-987e","script":"seal","character":"顾","reading":"gù","description":"⒈回头看瞻前～后。〈引〉看左～右盼。环～四周。\n⒉注意，照管，关心～全大局。照～。关～。奋不～身。\n⒊探望，拜访三～茅庐。\n⒋商店称来买货物的善待～客。优惠老～主。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顾"},{"id":"glyph-seal-987f","script":"seal","character":"顿","reading":"dùn","description":"用脚底或用脚使劲往下踩\n倒下,跌倒\n①稍停停～。\n②忽然；立刻～悟。\n③用头或手叩地～首。\n④处理；安置安～。\n⑤量词。用于吃饭、劝说等行为的次数三～饭。\n⑦姓。\n【顿挫】停顿转折。多形容声音和谐悦耳，节奏感强。\n【顿号】标点符号的一种，即'、'，表示一句话中并列的词或词组之间的停顿。\n【顿开茅塞】见【茅塞顿开】。\n【顿然】忽然；一下子。\n【顿首】叩头；磕头。旧时多用于书信的起头或末尾。\n顿dú 1.见\"冒顿\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顿"},{"id":"glyph-seal-9880","script":"seal","character":"颀","reading":"qí","description":"身材修长\n通恳”。诚恳\n通恳”。坚韧\n颀qí身材高硕人其～\n颀kěn 1.恻隐貌。 2.见\"颀典\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颀"},{"id":"glyph-seal-9881","script":"seal","character":"颁","reading":"bān","description":"又假借为攽”。颁发;分赏\n出御府珠玉玩好之物,颁\n颁 bān 颁布；发～奖。\n【颁行】发布施行。\n颁fén 1.大头貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颁"},{"id":"glyph-seal-9882","script":"seal","character":"颂","reading":"sòng","description":"这个意义后来写作容”\n占兆之词\n文体之一,指\n⒈赞扬，赞美～扬。歌～。\n⒉棕祝～。敬～。\n⒊一种文体，以赞扬为内容的诗歌或文章祖国～。\n⒋〈古〉在祭祀中使用的舞曲周～。鲁～。\n颂róng 1.仪容。 2.容受;收容。 3.宽容。 4.公开;明白。参见\"颂言\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颂"},{"id":"glyph-seal-9883","script":"seal","character":"颃","reading":"háng","description":"颈项\n咽喉\n鸟向下飞\n飞奔","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颃"},{"id":"glyph-seal-9884","script":"seal","character":"预","reading":"yù","description":"预先,事先。事先有准备。通豫”\n参与。通与”\n⒈在先，事前～先。～告。～言。～计。～约。～定。～防。～祝胜利。\n⒉加入，参加，参与～会。参～。干～其事。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-预"},{"id":"glyph-seal-9885","script":"seal","character":"颅","reading":"lú","description":"头,头颅\n额头\n颅盖\n颅骨\n颅腔","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颅"},{"id":"glyph-seal-9886","script":"seal","character":"领","reading":"lǐng","description":"领子,衣领\n要领\n山道,山坡\n⒈脖子引～北望。\n⒉衣服上围绕脖子的部分衣～子。\n⒊要点，纲要要～。纲～。提纲挈～。\n⒋带，引，统率～队。带～。率～。～兵百万。\n⒌接受，取得～教。失物招～。\n⒍了解，懂得，欣赏～会。～悟。～略。共～人间第一香。\n⒎占有，管辖占～。～土。～海。～空。～域。\n⒏量词锦裘三～。四～凉席。\n①率领并引导。\n②指领导人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-领"},{"id":"glyph-seal-9887","script":"seal","character":"颇","reading":"pō","description":"偏,倾斜,不平正\n偏邪,不公正\n⒈偏，偏差偏～。\n颇pǒ 1.不可。\n颇pí 1.参见\"颇我\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颇"},{"id":"glyph-seal-9888","script":"seal","character":"颈","reading":"jǐng","description":"器物像颈或部位相当于颈的部分\n脖子的前面部分\n⒈俗称\"脖子\"，头与躯干相连的部分引～高歌。\n⒉物体像颈的部分瓶～。\n颈gěng 1.见\"脖颈\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颈"},{"id":"glyph-seal-9889","script":"seal","character":"颉","reading":"jié","description":"仓颉”上古人名,相传他创造中国文字\n颈项僵直的\n鸟飞而下\n有花纹的缯\n⒉见xié。\n①鸟往上往下飞。\n②不相上下或对抗相互～颃。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颉"},{"id":"glyph-seal-988a","script":"seal","character":"颊","reading":"jiá","description":"侧,旁边\n堂内正室旁边的房间\n颊带","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颊"},{"id":"glyph-seal-988c","script":"seal","character":"颌","reading":"hé","description":"多数脊椎动物构成口腔上下部的骨骼和肌肉组织。上部称上颌;下部称下颌,俗称下巴”\n颔  ge\n⒈口。\n⒉见hé。\n⒈构成口腔上、下部的骨头和肌肉的统称，上部叫上～，下部叫下～。\n⒉见gé、hán、qīn。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颌"},{"id":"glyph-seal-988d","script":"seal","character":"颍","reading":"yǐng","description":"发源于河南省登封县,至安徽流入淮河\n颍yǐng蛴，发源于河南省登封，流到安徽省正阳关入淮河。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颍"},{"id":"glyph-seal-988e","script":"seal","character":"颎","reading":"jiǒng","description":"明亮；古同“炯”。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-988f","script":"seal","character":"颏","reading":"kē","description":"下颌下方或下颌支之间的表面,通称下巴”\n颏宽\n颏kē下巴颏儿，在两腮及嘴的下面。它是脸的最下部分。\n颏ké 1.鸟名用字。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颏"},{"id":"glyph-seal-9890","script":"seal","character":"颐","reading":"yí","description":"保养\n⒈面颊，腮以手支～。\n⒉养，保养～神。～养。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颐"},{"id":"glyph-seal-9894","script":"seal","character":"颔","reading":"hàn","description":"位于颈的前上方,相当于颏部的下方,结喉的上方\n⒈下巴底下满～白髭魀。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颔"},{"id":"glyph-seal-9896","script":"seal","character":"颖","reading":"yǐng","description":"锥芒\n⒈谷穗，禾的末端。稻、麦等禾本科植物小穗基部的苞片嘉禾重～。谷之～片。\n⒉东西末端的尖锐部分锥在袋中，～脱而出。\n⒊聪明幼便～悟。聪～过人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颖"},{"id":"glyph-seal-9897","script":"seal","character":"颗","reading":"kē","description":"多用于圆形或粒状物\n如三颗黄豆;两颗绿豆\n颗kē量词。指圆形或粒状物一～红心。三～珠子。五～星。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颗"},{"id":"glyph-seal-9898","script":"seal","character":"题","reading":"tí","description":"物品的前端或顶端\n⒊练习、考试等要求解答的问问～。试～。数学～。\n⒋写上，签署～写。～名。～款。～词。\n⒌评议品～。\n题dì 1.通\"睇\"。视。 2.通\"匙\"。歃血器。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-题"},{"id":"glyph-seal-9899","script":"seal","character":"颙","reading":"yóng","description":"头大；也形容恭敬、仰慕的样子。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-989b","script":"seal","character":"颛","reading":"zhuān","description":"善良\n顽愚\n通专”。专门\n专擅。通专”\n⒈愚昧。\n⒉通\"专\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颛"},{"id":"glyph-seal-989c","script":"seal","character":"颜","reading":"yán","description":"印堂,两眉之间\n额头\n面容,脸色\n体面,容誉\n⒈额～赤。〈引〉面容，容貌～面⊥～悦色。笑逐～开。无～见人。\n⒉色彩～色。～料。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颜"},{"id":"glyph-seal-98a0","script":"seal","character":"颠","reading":"diān","description":"泛指物体的顶部\n马的额头\n本,始\n古县名\n②同'巅'，高而直立的东西的顶端山～。\n③上下振动～簸。\n④跌落；倒下～覆。\n⑤同'癫'，神经错乱。\n【颠覆】采用阴谋手段从内部推翻合法政权。\n【颠沛流离】生活困苦，四处流浪。\n【颠扑不破】无论怎样摔打都弄不破。比喻思想、理论正确，无法驳倒。\n颠tián 1.见\"颠颠\"。 2.通\"阗\"。充满。参见\"颠实\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颠"},{"id":"glyph-seal-98a1","script":"seal","character":"颡","reading":"sǎng","description":"额头\n喉咙;嗓子\n稽颡”的省称,即叩头、磕头\n颡sǎng额。俗称\"脑门子\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颡"},{"id":"glyph-seal-98a2","script":"seal","character":"颢","reading":"hào","description":"浩大\n光明\n通昊”。本指西天,泛指天空","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颢"},{"id":"glyph-seal-98a4","script":"seal","character":"颤","reading":"chàn","description":"颤抖,发抖\n物体振动\n通惮”。惧怕,惊恐\n⒈振动～动。\n颤zhàn发抖，极其害怕～栗。打～‘～。胆～心惊。～ ～兢兢。\n颤shān 1.鼻通能辨气味。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颤"},{"id":"glyph-seal-98a6","script":"seal","character":"颦","reading":"pín","description":"忧愁\n颦pín皱眉头眉～。效～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颦"},{"id":"glyph-seal-98ce","script":"seal","character":"风","reading":"fēng","description":"空气流动形成的自然现象。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-98d1","script":"seal","character":"飑","reading":"biāo","description":"暴风\n飑云\n飑 biāo气象学上指风向突然改变，风速急剧增大的天气现象。\n飑páo 1.风大而急。\n飑pò 1.见\"飑飑\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-飑"},{"id":"glyph-seal-98d2","script":"seal","character":"飒","reading":"sà","description":"狂风拉物\n凋零;衰落\n飞舞\n⒊衰落，衰老庭树日衰～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-飒"},{"id":"glyph-seal-98d5","script":"seal","character":"飕","reading":"sōu","description":"象声词,同嗖”\n形容箭离弦之声\n小风\n寒冷;清凉。也单用作飕”\n象声词\n形容风声\n形容雨声\n风雨声飕飕催早寒,胡雁翅湿高飞难\n⒈风吹衣服已被风～干了。\n⒉同\"嗖\"。像声词。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-飕"},{"id":"glyph-seal-98d8","script":"seal","character":"飘","reading":"piāo","description":"飘扬,飞扬\n⒈旋风，大风～风。\n⒉随风摆动或飞扬～动。～摇。～扬。桂花～香§旗～ ～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-飘"},{"id":"glyph-seal-98d9","script":"seal","character":"飙","reading":"biāo","description":"泛指风\n迅疾\n飙biāo 1.旋风;暴风。 2.指风。 3.迅疾。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-飙"},{"id":"glyph-seal-98de","script":"seal","character":"飞","reading":"fēi","description":"泛指飞翔\n⒈鸟类或虫类等利用翅膀在空中活动小鸟群～。～蛾←蝶～。〈引〉物体在空中飘扬或行动，又指这些物体彩云～。大雪纷～。～砂走石。火箭起～。～行物。宇宙～船\n⒉快，极其迅速～步。～报。～舟。～腾。～跃。\n⒊极，非常这把剑～快。\n⒋形容高悬在空中的～桥。\n⒍意外的～祸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-飞"},{"id":"glyph-seal-98df","script":"seal","character":"食","reading":"shí；sì；yì","description":"shí：(1)吃～肉。～欲。\n(2)吃的东西～品。粮～。零～。丰衣足～。\n(3)俸禄君子谋道不谋～”。\n(4)日月亏缺或完全不见的现象日～。月～。\nsì：拿东西给人吃～母（乳母）。\nyì：用于人名郦～其（jī）（中国汉代人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-食"},{"id":"glyph-seal-98e7","script":"seal","character":"飧","reading":"sūn","description":"sūn：晚饭，亦泛指熟食，饭食。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-飧"},{"id":"glyph-seal-98e8","script":"seal","character":"飨","reading":"xiǎng","description":"设盛宴待宾客\n⒈受用，满足～受。～有。～福。共～太平。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-飨"},{"id":"glyph-seal-9910","script":"seal","character":"餐","reading":"cān","description":"cān：(1)吃～具。～厅。聚～。风～露宿。\n(2)饭食早～。西～。\n(3)量词，指一顿饭一日三～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-餐"},{"id":"glyph-seal-9954","script":"seal","character":"饔","reading":"yōng","description":"yōng：(1)熟食。\n(2)早饭～飧不继（飧”，晚饭，指吃了上顿没有下顿）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饔"},{"id":"glyph-seal-9955","script":"seal","character":"饕","reading":"tāo","description":"tāo：贪财，贪食老～。\n〔～餮〕ａ．传说中的一种凶恶贪食的野兽，古代铜器上面常用它的头部形状做装饰；ｂ．喻凶恶贪婪的人；ｃ．喻贪吃的人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饕"},{"id":"glyph-seal-9965","script":"seal","character":"饥","reading":"jī","description":"⒈饿，跟\"饱\"相对～饿难熬。～肠辘辘。～不择食。\n⒉灾荒，年收成不好～荒。～岁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饥"},{"id":"glyph-seal-9967","script":"seal","character":"饧","reading":"táng","description":"用麦芽或谷芽熬成的饴糖\n糖块、面剂子等变软\n形容眼色朦胧\n⒈麦芽或谷芽等熬成的糖。\n⒉糖块或面剂子等变软糖～了。面团～了。\n⒊精神不振，眼光朦胧两眼发～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饧"},{"id":"glyph-seal-9969","script":"seal","character":"饩","reading":"xì","description":"活的牲口\n生肉\n给养;俸禄\n⒈〈古〉指赠送人的谷物或饲料。〈引〉赠送。\n⒉〈古〉用于祭祀或馈赠的活牲口或生肉～羊。～献。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饩"},{"id":"glyph-seal-996a","script":"seal","character":"饪","reading":"rèn","description":"把食物做熟，如烹饪。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-996c","script":"seal","character":"饬","reading":"chì","description":"命令\n告诫。通敕”\n⒈整顿，整治整～。～武备。\n⒉谨慎谨～。\n⒊通\"敕\"。命令，告诫～令。～知。申～。\n饬shì 1.装饰；修饰。 2.巧饰；巧伪。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饬"},{"id":"glyph-seal-996d","script":"seal","character":"饭","reading":"fàn","description":"给人喂饭或喂牲口\n含。古代将米贝珠玉之类放\n⒈熟的谷物食品，多指大米饭这～好吃。这～好香哟！\n⒉进食，定时吃的食品能～否？开～了。吃晚～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饭"},{"id":"glyph-seal-996e","script":"seal","character":"饮","reading":"yǐn","description":"⒈喝～茶。～酒。～水思源。水浊不可～。\n⒉可以喝的东西～料。冷～。\n⒊含，忍～泣。～恨。\n饮yìn给牲口喝水～马渭水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饮"},{"id":"glyph-seal-996f","script":"seal","character":"饯","reading":"jiàn","description":"送行\n以蜜、浓糖浆浸渍的果品\n⒈用酒、食送行～行。～别。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饯"},{"id":"glyph-seal-9970","script":"seal","character":"饰","reading":"shì","description":"装饰;修饰\n⒈装修得好看装～。修～。粉～。\n⒉指装饰品首～。服～。\n⒊假托，遮掩～词。掩～。文过～非。\n⒋扮演她在这个剧里～主角。\n饰chì 1.整治;整顿。 2.端正;谨慎。 3.戒备。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饰"},{"id":"glyph-seal-9971","script":"seal","character":"饱","reading":"bǎo","description":"充足,多\n饱满\n满足\n既醉以酒,既饱以德。\n①食量得到了满足，与'饿'相反吃～喝足。\n②饱满谷淋～。\n③丰富；充分～学之士、～经忧患。\n④满足大～眼福。\n【饱和化合物】饱和烃及其衍生物。其分子中碳-碳原子间完全以单键相连结。\n【饱和链烃】见【烷烃】。\n【饱和汽】如果汽跟产生这种汽的液体处于动态平衡状态时，这种汽就称为该液体的饱和汽。\n【饱和溶液】在一定温度下，溶液里所溶解的某种溶质如果不能再增加，这样的溶液称为这种溶质的饱和溶液。饱和溶液处于溶解平衡状态。\n【饱经风霜】经历过长时期艰苦生活的磨练。\n【饱食终日】吃得饱饱地打发日子。形容无所事事。\n【饱学】学识丰富～之士。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饱"},{"id":"glyph-seal-9974","script":"seal","character":"饴","reading":"yí","description":"⒈用谷、麦芽等制成的糖浆，糖稀～糖。甘如～蜜。\n⒉某种糖果高粱～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饴"},{"id":"glyph-seal-9975","script":"seal","character":"饵","reading":"ěr","description":"钓鱼用的鱼食\n药饵\n食物的总称\n筋腱\n吞食\n①糕饼果～。\n②钓鱼用的鱼食鱼～。\n③引诱以此～敌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饵"},{"id":"glyph-seal-9976","script":"seal","character":"饶","reading":"ráo","description":"富裕,丰足\n余;剩\n⒉宽容，宽恕～恕。～他这一次。\n⒊添～上两元。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饶"},{"id":"glyph-seal-9977","script":"seal","character":"饷","reading":"xiǎng","description":"招待,供给或提供\n有童子以黍肉\n⒈军粮，又指军、警等的薪金粮～。关～。领～。\n⒉给在田间劳动的人送饭。\n⒊同\"飨\"。用酒饮食款待人～客。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饷"},{"id":"glyph-seal-997c","script":"seal","character":"饼","reading":"bǐng","description":"形状像饼的东西\n做饼\n饼铛\n饼肥\n饼干\n饼子\n用玉米面、小米面等贴在锅上\n①烤熟或蒸熟的面食的总称。形状多扁且圆～干、烤～。\n②形状像饼的东西铁～、柿～。\n【饼饵】饼类食品的泛称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饼"},{"id":"glyph-seal-997f","script":"seal","character":"饿","reading":"è","description":"使受饿;感到饥饿\n①肚子没食，想吃东西。\n②使受饿别～着。\n【饿莩】见【饿殍】。\n【饿殍】饿死的人。又作饿莩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饿"},{"id":"glyph-seal-9981","script":"seal","character":"馁","reading":"něi","description":"气馁;泄气,丧气\n⒈饥饿冻饿冻～。〈喻〉失掉勇气气～。胜不骄败不～。\n⒉鱼腐烂，不新鲜鱼～而肉败。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馁"},{"id":"glyph-seal-9986","script":"seal","character":"馆","reading":"guǎn","description":"⒈接待宾客或旅客居住或食宿的房屋宾～。旅～。\n⒉某些服务性的商店饭～。茶～儿。美容～。\n⒊外交人员在别国常驻的处所领事～。大使～。\n⒋展示物品、陈列文物或进行文化活动的场所展览～。博物～。文化～。图书～。科技～。\n⒌〈古〉教书的地方蒙～。家～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馆"},{"id":"glyph-seal-9988","script":"seal","character":"馈","reading":"kuì","description":"进食\n烹调\n赠送\n⒈赠送～赠。\n⒉吃饭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馈"},{"id":"glyph-seal-998f","script":"seal","character":"馏","reading":"liú","description":"通过加热使物质分离或分解\n馏liù将凉的熟食蒸热把包子～一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馏"},{"id":"glyph-seal-9991","script":"seal","character":"馑","reading":"jǐn","description":"谷物欠收\n通殣”。饿死。饿死的人\n馑 〈动〉\n缺乏\n馑jǐn饥荒饥～之年。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馑"},{"id":"glyph-seal-9994","script":"seal","character":"馔","reading":"zhuàn","description":"吃喝;给吃喝\n一般的食品、食物\n⒉吃，喝有酒食，先生～。\n馔xuǎn 1.古重量单位。一馔等于六两。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馔"},{"id":"glyph-seal-9996","script":"seal","character":"首","reading":"shǒu","description":"shǒu：(1)头，脑袋～饰。～级。～肯（点头表示同意）。\n(2)领导的人，带头的～领。元～。～脑。～相（xiàng）。\n(3)第一，最高～都（dū）。～府。\n(4)最先，最早～次。～届。～创。～日封。～义（首先起义）。\n(5)出头告发自～。出～。\n(6)量词，指诗和歌一～诗。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-首"},{"id":"glyph-seal-9997","script":"seal","character":"馗","reading":"kuí","description":"kuí：同逵”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馗"},{"id":"glyph-seal-9999","script":"seal","character":"香","reading":"xiāng","description":"xiāng：(1)气味好闻，与臭”相对～味。～醇。芳～。清～。\n(2)舒服睡得～。\n(3)味道好这鱼做得真～。\n(4)受欢迎这种货物在农村～得很。\n(5)称一些天然或人造的有香味的东西麝～。灵猫～。龙涎～。檀～。沉～。\n(6)旧时用以形容女子事物或作女子的代称～闺。～艳。\n(7)祭祖、敬神所烧的用木屑搀上香料做成的细条～火。烧～拜佛。～炉。～烛。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-香"},{"id":"glyph-seal-99a5","script":"seal","character":"馥","reading":"fù","description":"fù：香气～～（香气浓烈）。～郁（香气浓烈）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馥"},{"id":"glyph-seal-99a8","script":"seal","character":"馨","reading":"xīn","description":"xīn：(1)散布很远的香气～香。如兰之～。\n(2)喻长存的英名垂～千祀。\n(3)助词，作用同样”宁～（这样，如此）。宁～儿（原意是这样的儿子”，后用以赞美孩子或子弟）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馨"},{"id":"glyph-seal-9a6c","script":"seal","character":"马","reading":"mǎ","description":"单蹄食草大型哺乳动物\n⒈家畜。耳小直立，面长，颈上缘有鬃，尾巴有长毛，四肢强健，善跑，供人骑或拉东西等。皮可制革。\n⒉通\"码\"筹～。\n⒑［马到成功］战马一到就胜利了。形容迅速地取得胜利。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-马"},{"id":"glyph-seal-9a6d","script":"seal","character":"驭","reading":"yù","description":"控制,制约\n统治;治理\n⒈驾驭车马～车。又指驾驭车马的人～手。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驭"},{"id":"glyph-seal-9a6e","script":"seal","character":"驮","reading":"tuó","description":"驮着货物的牲口或牲口所负载的货物\n负载\n⒈用背负载马～着盐巴。她背上～了个孩子。\n驮duò 1.驮着货物的牲口或指牲口所驮的货物。 2.量词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驮"},{"id":"glyph-seal-9a6f","script":"seal","character":"驯","reading":"xùn","description":"泛指顺服\n⒈顺从，听从指使～服。善于～兽。\n⒉善良～行。\n驯xún 1.马顺服。 2.泛指顺服。 3.使驯服，使和顺。 4.顺，不背理﹑不乱。 5.调顺，使和谐不乱。 6.美善。 7.循序渐进。 8.熟习。 9.通\"训\"。教训，教导\n。 10.通\"训\"。训释，解说。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驯"},{"id":"glyph-seal-9a70","script":"seal","character":"驰","reading":"chí","description":"又驱使\n疾行\n②传扬～名中外。\n【驰名】声名远扬。又作驰誉。\n【驰誉】见【驰名】。\n【驰骤】奔驰纵横～。\n⒈奔跑，使劲赶马。〈引〉车马疾行奔～。～骋。疾～。特指驱马进击将～之。\n⒉向往心～神往。\n⒊传扬～名中外。\n驰tuó 1.参见\"橐驰\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驰"},{"id":"glyph-seal-9a71","script":"seal","character":"驱","reading":"qū","description":"赶马\n并驱从两牡兮。\n冯谖先\n⒈赶马。〈引〉赶，赶走～马。～虫。～逐。～车前进。\n⒉快跑驰～。并驾齐～。长～直入。\n①差遣，迫使～使他去干。\n②推动为好奇心所～使。\n驱ōu 1.捶击，殴打。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驱"},{"id":"glyph-seal-9a73","script":"seal","character":"驳","reading":"bó","description":"驳杂;庞杂\n①指出对方的意见不合事理或无道理；用自己的意见否定别人的意见反～。\n②一种颜色夹杂着别种颜色；不纯净斑～陆离。\n③驳运；在岸与船，船与船之间用小船来回运输～运。\n④驳船。无动力装置，由拖轮拉着或推着行驶的船铁～。\n【驳船】分装、转运货物或旅客的船只，一般无动力装置，而由拖轮推、拉航行。\n【驳回】指法院拒绝诉讼当事人、法定代理人或检察院提出的申请和要求。\n【驳论】议论方法之一。即直接揭露某事物的错误本质，批驳某主张的反动性质，痛斥某行为的严重桅。特点是措辞激烈，笔锋犀利，逻辑性强，语言一针见血，多用反问句\n、判断句、否定句。\n【驳难】反驳责难。\n【驳杂】不纯净，杂乱论文内容～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驳"},{"id":"glyph-seal-9a74","script":"seal","character":"驴","reading":"lǘ；lv","description":"驴不胜怒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驴"},{"id":"glyph-seal-9a77","script":"seal","character":"驷","reading":"sì","description":"古代套在一辆车上的四匹马，也指套有四马的车。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9a78","script":"seal","character":"驸","reading":"fù","description":"又指驾副车的马\n通辅”。车厢外的立木。引申为辅助\n⒈几匹马共同拉车，位于旁边的马叫\"驸\"。\n【驸马】汉代有\"驸马都尉\"的官，原来是近侍官的一种，后来皇帝的女婿常做这个官，因而驸马又专指公主的丈夫。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驸"},{"id":"glyph-seal-9a79","script":"seal","character":"驹","reading":"jū；jv","description":"泛指少壮的马\n⒈好马千里～。\n驹jù 1.见\"驹丽\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驹"},{"id":"glyph-seal-9a7b","script":"seal","character":"驻","reading":"zhù","description":"古时特指车驾停立\n驻zhù 1.车马停止。 2.停留。 3.止住;阻止。 4.留住。 5.居留其地。 6.指居住。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驻"},{"id":"glyph-seal-9a7e","script":"seal","character":"驾","reading":"jià","description":"把鞍加在马背上\n骑;乘\n操纵;驾驶\n晓驾炭车辗\n①对人员的管理及使用。\n②掌握，控制知识越多，～驭的能力越强。\n驾jiā 1.添加;增多。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驾"},{"id":"glyph-seal-9a7f","script":"seal","character":"驿","reading":"yì","description":"即孟子置郵,所谓遽也。\n馹为传车,驿为马骑。\n驿站","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驿"},{"id":"glyph-seal-9a80","script":"seal","character":"骀","reading":"dài","description":"疲钝\n舒缓放荡。常作骀荡”\n骀荡\n春风骀荡\n骀〈名〉\n比喻庸才\n骀dài 1.无所局限;舒缓广大。 2.疲钝。\n骀tāi 1.古国名。故治在今陕西省武功县西南。 2.古邑名。故治在今山东省诸城市东南。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骀"},{"id":"glyph-seal-9a81","script":"seal","character":"骁","reading":"xiāo","description":"勇捷\n⒈好马。\n⒉勇猛，矫健～猛。～将。～勇。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骁"},{"id":"glyph-seal-9a82","script":"seal","character":"骂","reading":"mà","description":"增益。通雈”\n痛斥\n⒈用粗野的话侮辱人辱～。莫～人。\n⒉用严厉的话斥责～了他。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骂"},{"id":"glyph-seal-9a84","script":"seal","character":"骄","reading":"jiāo","description":"骄 〈形〉\n马雄壮,泛指高大雄壮\n傲慢;骄矜\n⒉自满，自高自大～傲自满。～兵必败。戒～戒躁。〈引〉放纵～奢淫逸。\n⒊猛烈～阳灼人。\n①自高自大，瞧不起别人～傲使人落后。\n②自豪祖国的～傲。值得～傲。\n骄xiāo 1.犬名。参见\"歇骄\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骄"},{"id":"glyph-seal-9a86","script":"seal","character":"骆","reading":"luò","description":"哔哔骆马。\n骆驼\n通络”。络绎不绝\n骆jià 1.见\"骆田\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骆"},{"id":"glyph-seal-9a87","script":"seal","character":"骇","reading":"hài","description":"惊骇;惊诧;惊动\n震动\n骇hài马受惊马～。〈引〉惊恐，害怕惊涛～浪。～人听闻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骇"},{"id":"glyph-seal-9a88","script":"seal","character":"骈","reading":"pián","description":"并列\n并联;合并\n曹共公闻其骈胁。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骈"},{"id":"glyph-seal-9a8a","script":"seal","character":"骊","reading":"lí","description":"深黑色的马\n山名。骊山\n古邑名\n⒈纯黑色的马。\n⒉两马 并驾。\n骊chí 1.见\"骊靬\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骊"},{"id":"glyph-seal-9a8b","script":"seal","character":"骋","reading":"chěng","description":"放任,放纵\n施展;发挥\n古州名\n【骋怀】开怀。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骋"},{"id":"glyph-seal-9a8c","script":"seal","character":"验","reading":"yàn","description":"证据;凭证\n效验,灵验\n征象;征兆\n检查;检验\n⒈检查，察看～血。～光。～收。～证。\n⒉效果效～。应～。\n⒊〈古〉证据，凭证何以为～？","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-验"},{"id":"glyph-seal-9a8e","script":"seal","character":"骎","reading":"qīn","description":"形容马快跑的样子，也引申为迅速前进。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9a8f","script":"seal","character":"骏","reading":"jùn","description":"天子赐许男骏马十六。\n才能出众的人\n迅速\n⒈好马～马。八～日行三万里。〈引〉急速～奔。\n⒉〈古〉通\"峻\"。高而陡峭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骏"},{"id":"glyph-seal-9a90","script":"seal","character":"骐","reading":"qí","description":"骏马\n通麒”。麒麟\n骐骥\n⒈有青黑色纹理的马。\n⒉青黑色的。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骐"},{"id":"glyph-seal-9a91","script":"seal","character":"骑","reading":"qí","description":"跨于物上或两边叫骑,跨坐\n⒈两腿跨坐在牲畜或其它东西上～马。～驴。～摩托车。\n⒉骑的马或其它牲畜坐～。\n⒊指骑兵轻～。铁～。也泛指骑马的人单～。\n⒋兼跨两边～缝盖章。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骑"},{"id":"glyph-seal-9a93","script":"seal","character":"骓","reading":"zhuī","description":"毛色苍白相杂的马\n骓zhuī毛色青白混杂的马乌～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骓"},{"id":"glyph-seal-9a96","script":"seal","character":"骖","reading":"cān","description":"驾车时在两边的马\n骖cān古代驾在车前两侧的马。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骖"},{"id":"glyph-seal-9a98","script":"seal","character":"骘","reading":"zhì","description":"安定\n评定;评论\n⒈公马。\n⒉定评～优劣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骘"},{"id":"glyph-seal-9a9a","script":"seal","character":"骚","reading":"sāo","description":"骚动;动乱\n通搔”。抓,挠,以指甲轻刮\n其人坚劲,寡有疥骚,终无瘠酲。╠\n⒈动乱，扰乱，不安定～动。～乱。～扰。\n⒊同\"臊\"。一种臭味，特指狐腋臭～气。\n②原指姿容俏丽，后多指妇女言行轻佻。\n骚sǎo 1.全部;尽数。\n骚xiāo 1.地名用字。蒲骚，春秋地名，在今湖北省应城市西北。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骚"},{"id":"glyph-seal-9a9b","script":"seal","character":"骛","reading":"wù","description":"追求;强求。也作务”\n迅速\n⒈乱跑，纵横驰骋。\n⒉通\"务\"。追求。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骛"},{"id":"glyph-seal-9a9c","script":"seal","character":"骜","reading":"ào","description":"放纵奔驰\n通傲”。骄傲\n⒈骏马或马不驯良骥～。\n⒉不驯顺桀～不驯。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骜"},{"id":"glyph-seal-9a9d","script":"seal","character":"骝","reading":"liú","description":"黑鬣、黑尾巴的红马。泛指骏马","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骝"},{"id":"glyph-seal-9a9e","script":"seal","character":"骞","reading":"qiān","description":"也指其他动物的肚腹低陷\n通蹇”。跛足","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骞"},{"id":"glyph-seal-9aa0","script":"seal","character":"骠","reading":"biāo","description":"⒈马快跑的样子。\n⒉骁勇～悍。\n骠biāo 1.黄色有白斑或黄色白鬃尾的马。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骠"},{"id":"glyph-seal-9aa2","script":"seal","character":"骢","reading":"cōng","description":"青白杂毛的马。今名菊花青马\n泛指马\n骢cōng青白足的马。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骢"},{"id":"glyph-seal-9aa4","script":"seal","character":"骤","reading":"zhòu","description":"使马奔驰\n泛指奔驰\n迅疾,猛快\n飘风不终朝,骤雨不终\n⒈马奔驰弛～。〈引〉急速，快速暴风～雨。\n⒉忽然，突然～然。狂风～起。天色～变。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骤"},{"id":"glyph-seal-9aa5","script":"seal","character":"骥","reading":"jì","description":"比喻杰出的人才\n骥骜","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骥"},{"id":"glyph-seal-9aa7","script":"seal","character":"骧","reading":"xiāng","description":"腾跃;昂首奔驰\n仰;上举\n后右足白的马\n泛指马\n⒈马抬起头快跑。\n⒉上举，高举。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骧"},{"id":"glyph-seal-9aa8","script":"seal","character":"骨","reading":"gǔ；gū","description":"gǔ：(1)人和脊惟动物身体里面支持身体保护内脏的坚硬组织～头。～胳（全身骨头的总称）。～节。～肉（ａ．指最亲近的有血统关系的人，亦称骨血”；ｂ．喻紧密相连，不可分割的关系）。～干（gàn）。\n(2)像骨的东西（指支撑物体的骨架）伞～。扇～。\n(3)指文学作品的理论和笔力～力（ａ．雄健的笔力；ｂ．刚强不屈的气概）。风～（古典文艺理论术语，指文章的艺术风格，亦指作品的风神骨髓）。\n(4)指人的品质、气概侠～。～气。\ngū：〔～朵儿（duor）〕尚未开放的花朵。\n〔～碌〕滚动（碌”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骨"},{"id":"glyph-seal-9ab8","script":"seal","character":"骸","reading":"hái","description":"hái：(1)骨头～骨。尸～。\n(2)身体病～。残～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骸"},{"id":"glyph-seal-9abc","script":"seal","character":"骼","reading":"gé","description":"gé：骨头骨～（亦作骨胳”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骼"},{"id":"glyph-seal-9ac0","script":"seal","character":"髀","reading":"bì","description":"bì：大腿，亦指大腿骨～肉复生（因长久不骑马，大腿肉又长起来了，形容长久安逸，无所作为）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髀"},{"id":"glyph-seal-9ac1","script":"seal","character":"髁","reading":"kē","description":"kē：骨头上的突起，多长在骨头的两端，亦指大腿骨或膝盖骨。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髁"},{"id":"glyph-seal-9ac5","script":"seal","character":"髅","reading":"lóu","description":"死人头骨。亦泛指骸骨","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髅"},{"id":"glyph-seal-9acb","script":"seal","character":"髋","reading":"kuān","description":"臀部\n髋骨,通称胯骨\n⒈大腿的上部～部。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髋"},{"id":"glyph-seal-9acc","script":"seal","character":"髌","reading":"bìn","description":"古代除去膝盖骨的酷刑。\n②髌骨膝盖部的一块骨，略呈三角形，尖端朝下。又叫膝盖骨。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髌"},{"id":"glyph-seal-9ad1","script":"seal","character":"髑","reading":"dú；dū","description":"dū：〔～髅〕死人的头骨，骷髅。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髑"},{"id":"glyph-seal-9ad3","script":"seal","character":"髓","reading":"suǐ","description":"suǐ：(1)骨头的空腔中像胶状的东西骨～。精～（喻精华）。\n(2)像骨髓的东西脊～。脑～。延～（后脑的一部分）。\n(3)植物茎的中心部分，由薄壁的细胞组成。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髓"},{"id":"glyph-seal-9ad8","script":"seal","character":"高","reading":"gāo","description":"gāo：(1)由下到上距离大的，与低”相对～峰。～空。～踞。～原。～耸。～山流水（喻知己、知音或乐曲高妙）。～屋建瓴（形容居高临下的形势）。～瞻远瞩。\n(2)高度他身～一米八。\n(3)等级在上的～级。～考。\n(4)在一般标准或平均程度之上～质量。～消费。～价。～档。～手。～能物理。\n(5)声音响亮引吭～歌。\n(6)敬辞，称别人的事物～见。～就。～论。～寿。～堂。～徒。\n(7)热烈、盛大～昂。兴～采烈。\n(8)显贵，道德水平高崇～。清～。～风亮节。～尚。～雅。～洁。\n(9)宗族中最在上之称～祖。\n(10)酸根或化合物中比标准酸根多含一个氧原子的～锰酸钾。\n(11)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-高"},{"id":"glyph-seal-9ae1","script":"seal","character":"髡","reading":"kūn","description":"kūn：(1)古代剃去男子头发的一种刑罚～首（剃去头发，光头）。～钳（剃去头发，并用铁圈束颈）。\n(2)古代指和尚。\n(3)古代称修剪树枝。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髡"},{"id":"glyph-seal-9ae6","script":"seal","character":"髦","reading":"máo","description":"máo：(1)古代称幼儿垂在前额的短发。\n(2)毛中的长毫，喻英俊杰出之士～硕。～士。～俊。\n(3)指马鬃～马。\n(4)古同牦”，牦牛。\n〔时～〕时兴的，如～～的服装”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髦"},{"id":"glyph-seal-9aeb","script":"seal","character":"髫","reading":"tiáo","description":"tiáo：古代小孩头上扎起来的下垂头发垂～。～年（指幼年）。～龄。～龀（指童年）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髫"},{"id":"glyph-seal-9afb","script":"seal","character":"髻","reading":"jì","description":"jì：盘在头顶或脑后的发结～丫。～鬟。发～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髻"},{"id":"glyph-seal-9b08","script":"seal","character":"鬈","reading":"quán","description":"quán：(1)头发好，引申为美好。\n(2)头发卷曲。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鬈"},{"id":"glyph-seal-9b13","script":"seal","character":"鬓","reading":"bìn","description":"鬓发\n鬓角\n鬓脚\n鬓 bìn鬓角。耳朵前边长头发的部位。也指长在那里的头发双～斑白。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鬓"},{"id":"glyph-seal-9b1f","script":"seal","character":"鬟","reading":"huán","description":"huán：古代妇女梳的环形发髻云～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鬟"},{"id":"glyph-seal-9b23","script":"seal","character":"鬣","reading":"liè","description":"liè：(1)马、狮子等颈上的长毛～鬃。刚～。\n(2)鱼颔旁小鳍。\n(3)扫帚的末端。\n〔～狗〕哺乳动物，外形略像狗，头比狗的头短而圆，毛棕黄或棕褐色，有许多不规则的黑褐斑点，多生长在热带或亚热带地区，吃兽类尸体腐烂的肉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鬣"},{"id":"glyph-seal-9b32","script":"seal","character":"鬲","reading":"gé","description":"gé：〔～津河〕古水名，即今漳卫新河，是中国河北、山东两省的界河。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鬲"},{"id":"glyph-seal-9b3b","script":"seal","character":"鬻","reading":"yù","description":"yù：(1)卖～歌。～画。～文为生。卖儿～女。\n(2)古同育”，养育。\n〔淫～〕水流溪谷之间。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鬻"},{"id":"glyph-seal-9b3c","script":"seal","character":"鬼","reading":"guǐ","description":"guǐ：(1)某些宗教或迷信的人所说的人死后的灵魂～魂。～魅。～蜮（ａ．鬼怪；ｂ．阴险害人的）。\n(2)阴险，不光明～话。～黠。～胎。\n(3)对人的蔑称或憎称酒～。烟～。～子。吝啬～。\n(4)恶劣，糟糕（限做定语）～天气。\n(5)机灵，敏慧（多指小孩子）～精灵。\n(6)表示爱昵的称呼小～。机灵～。\n(7)星名，二十八宿之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鬼"},{"id":"glyph-seal-9b41","script":"seal","character":"魁","reading":"kuí","description":"kuí：(1)为首的，居第一位的～首。～星（ａ．北斗星中第一星，又第一星至第四星的总称；ｂ．中国神话中所说的主宰文章兴衰的神）。～元。罪～祸首。夺～。\n(2)高大身～力壮。～梧。～伟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魁"},{"id":"glyph-seal-9b42","script":"seal","character":"魂","reading":"hún","description":"hún：(1)迷信的人指附在人体上主宰人，又可离开肉体而独立存在的实体～灵。鬼～。～不附体。\n(2)指精神或情绪～飞魄散（形容极度惊恐）。～不守舍。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魂"},{"id":"glyph-seal-9b43","script":"seal","character":"魃","reading":"bá","description":"bá：传说中造成旱灾的鬼怪旱～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魃"},{"id":"glyph-seal-9b44","script":"seal","character":"魄","reading":"pò","description":"pò：(1)指依附形体而存在的精神魂～。丢魂落～。魂飞～散。\n(2)精神，精力～力。气～。体～。\n(3)古同霸”，月始生或将灭时的微光。\n(4)古同粕”，糟粕。\n(5)古同珀”，琥珀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魄"},{"id":"glyph-seal-9b45","script":"seal","character":"魅","reading":"mèi","description":"mèi：传说中的鬼怪鬼～。\n〔～力〕很能吸引人的力量。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魅"},{"id":"glyph-seal-9b47","script":"seal","character":"魇","reading":"yǎn","description":"迷糊;迷惑","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魇"},{"id":"glyph-seal-9b51","script":"seal","character":"魑","reading":"chī","description":"chī：〔～魅〕传说中指山林里能害人的怪物，如～～魍魉”（指各种各样的坏人）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魑"},{"id":"glyph-seal-9b54","script":"seal","character":"魔","reading":"mó","description":"mó：(1)宗教或神话传说中指害人性命、迷惑人的恶鬼，喻邪恶的势力～王。～爪。～怪。～鬼。～掌。～窟。恶～。妖～。病～。\n(2)不平常，奇异的～力。～术。～怔（举动异常，像有精神病。怔”读轻声）。～法。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魔"},{"id":"glyph-seal-9c7c","script":"seal","character":"鱼","reading":"yú","description":"完全水生并在水中呼吸的有头冷血脊椎动物,包括圆口类、板鳃类和具有软骨或硬骨骨骼的高等有鳃水生脊椎动物\n养～致富。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鱼"},{"id":"glyph-seal-9c81","script":"seal","character":"鲁","reading":"lǔ","description":"迟钝,愚钝\n莽撞,粗野\n中国春秋时国名\n⒈笨，愚钝～钝。\n⒊周代诸侯国名，在今山东省南部一带。\n⒋山东省的简称。\n鲁lǚ 1.陈述。 2.旅行。参见\"鲁飔\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲁"},{"id":"glyph-seal-9c82","script":"seal","character":"鲂","reading":"fáng","description":"魚名。鳊鱼的古称\n鱼名,似鳊鱼,银灰色,腹部隆起\n比喻人的劳苦\n鲂 fáng鲂鱼，与鳊鱼相似。体扁侧，银白色。头小而尖。腹部隆起。武昌鱼就是鲂鱼的一种。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲂"},{"id":"glyph-seal-9c85","script":"seal","character":"鲅","reading":"bà","description":"鲅bō 1.鱼掉尾而游貌。参见\"鲅鲅\"。 2.鱼名。形状似鲤而色赤的鱼，赤鲤。\n鲅bà 1.鱼名。亦称蓝点鲅﹑马鲛鱼﹑燕鱼。体略呈纺锤形。口大。鳞细。背黑蓝色，腹侧银灰色。生活于海洋。肉可食。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲅"},{"id":"glyph-seal-9c87","script":"seal","character":"鲇","reading":"nián","description":"鲇鱼\n鲇nián鱼名。～鱼，体前部扁平，后部扁侧，灰黑色，有羞。皮有粘质，无鳞。头大口宽。生活在淡水中，可供食用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲇"},{"id":"glyph-seal-9c8b","script":"seal","character":"鲋","reading":"fù","description":"鲫鱼\n蛤蟆\n鲋 fù古书上指鲫鱼。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲋"},{"id":"glyph-seal-9c8d","script":"seal","character":"鲍","reading":"bào","description":"盐腌的鱼\n鲍鱼,鳆鱼的别名。即石决明\n腹足纲前鳃亚纲鲍科鲍属海产贝类\n古代鞣制皮革的工人\n鲍老\n①见【鲍鱼】。\n②姓。\n【鲍叔牙】春秋时齐国大夫。生卒年不详。以能了解别人著称。少时与管仲友善。襄公乱政时，随公子凶出奔莒，凶成为国君后欲任鲍叔牙为宰，他却力举管仲◇齐国在管仲治理下，成为霸主。\n【鲍鱼】\n①咸鱼。\n②软体动物，贝类。生活在海中，肉可食，贝壳入中药。\n鲍bāo 1.人名用字。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲍"},{"id":"glyph-seal-9c90","script":"seal","character":"鲐","reading":"tái","description":"鲐鱼,也称鲭、油筒鱼、青花鱼\n代称老年人\n鲐tái鱼名。鲐鱼俗称\"鲐巴鱼\"、\"油筒鱼\"。鲐鱼，体呈纺锤形，背部青兰色，腹部淡黄色。生活在海里，可供食用。\n鲐yí 1.河豚。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲐"},{"id":"glyph-seal-9c94","script":"seal","character":"鲔","reading":"wěi","description":"鲟鱼和鳇鱼的古称\n鲔鱼\n白鲟的古称。又名象鱼、剑鱼、琴鱼\n耳。为中国特产\n鲔wěi〈古〉指鲟鱼。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲔"},{"id":"glyph-seal-9c9b","script":"seal","character":"鲛","reading":"jiāo","description":"动物名。中鲨鱼\n鲛jiāo沙鱼。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲛"},{"id":"glyph-seal-9c9c","script":"seal","character":"鲜","reading":"xiān","description":"假借为鱻。鲜鱼,活鱼\n鲜美的食物\n⒈新的，不干枯的～花。～鱼。～笋。～血。新～。尝～。\n⒉味美～汤。\n⒊鱼、虾等产品河～。～。\n⒋光彩，明亮～艳。～红。～明。\n鲜xiàn 1.通\"献\"。进献。 2.姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲜"},{"id":"glyph-seal-9ca0","script":"seal","character":"鲠","reading":"gěng","description":"病患,祸害\n假借为骾”。鱼刺卡在喉咙里\n阻塞;堵塞\n通哽”\n⒈鱼骨，鱼刺。\n⒉骨头卡在喉咙里。\n鲠biān 1.鳊鱼。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲠"},{"id":"glyph-seal-9ca1","script":"seal","character":"鲡","reading":"lí","description":"鱼名\n鲡lǐ 1.乌鳢鱼。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲡"},{"id":"glyph-seal-9ca2","script":"seal","character":"鲢","reading":"lián","description":"鲢鱼\n鲢lián鱼名。也叫\"白鲢\"。体侧扁，银白色，头小，鳞细。它是我国常见的淡水食用鱼之一。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲢"},{"id":"glyph-seal-9ca4","script":"seal","character":"鲤","reading":"lǐ","description":"鲤鱼\n一种软鳍淡水鱼,素栖于池塘或缓流中,主要吃植物性食物,可长得相当大,有时能活得很长,原为亚洲产物\n书信的代称\n鲤庭\n鲤lǐ鱼名。鲤鱼体侧扁，嘴边有长短须各一对。生活在淡水中，它是常见的养殖鱼类之一，供食用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲤"},{"id":"glyph-seal-9ca7","script":"seal","character":"鲧","reading":"gǔn","description":"鱼名。古书上指一种大鱼\n古人名,夏禹的父亲\n⒈〈古〉传说中的一种大鱼。\n⒉〈古〉人名。夏朝，禹的父亲。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲧"},{"id":"glyph-seal-9ca9","script":"seal","character":"鲩","reading":"huàn","description":"鱼名。即草鱼”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲩"},{"id":"glyph-seal-9cab","script":"seal","character":"鲫","reading":"jì","description":"鲫鱼,亦称鲋”\n鲫溜\n鲫jì鲫鱼，体侧扁，背脊隆起，无触须，头小，背青褐色，腹银白色。生活在淡水中，供食用。变种\"金鱼\"供观赏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲫"},{"id":"glyph-seal-9cb5","script":"seal","character":"鲵","reading":"ní","description":"小鱼\n鲵ní受保护的两栖动物。头扁平，眼小口大，四肢短，尾巴扁。有大～和小～两种，大～俗称\"娃娃鱼\"。生活在淡水中，禁止猎杀食用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲵"},{"id":"glyph-seal-9cb7","script":"seal","character":"鲷","reading":"diāo","description":"鲷科鱼的总称\n鲷diāo 1.鱼类的一属。身体侧扁，背部微凸。头大，口小。侧线发达。生活于海洋。有真鲷﹑黑鲷﹑长棘鲷等。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲷"},{"id":"glyph-seal-9cb8","script":"seal","character":"鲸","reading":"jīng","description":"大;巨大\n鲸波\n⒈鱼名。鲸鱼，属受保护的动物，禁止猎杀。它是生活在海洋里的哺乳动物，形状像鱼，胎生，肺呼吸，鼻孔位于头顶部。大小因种而异，小的长约一米；大的可达三十米，是\n现在世界上最大的动物。肉可吃，肝可制鱼肝油，脂肪可做油。\n鲸qíng 1.水栖哺乳纲动物。体形长大，外形似鱼，小约1米，大至30米。头大，眼小，耳壳退化。前肢呈鳍状，后肢退化。尾鳍叉形，呈水平状。成体皮肤无毛，皮下脂肪增\n厚，用肺呼吸，可潜水一刻钟至一小时。胎生。皮﹑肉﹑脂肪均可利用。鲸的种类很多，如蓝鲸﹑抹香鲸﹑海豚﹑江豚以及我国特有的淡水海豚即白暨豚等都属于鲸类。 2.指","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲸"},{"id":"glyph-seal-9cbd","script":"seal","character":"鲽","reading":"dié","description":"比目鱼的一种\n鲽dié 1.鱼名。比目鱼的一类。即鲽科比目鱼。体侧扁，像薄片，长椭圆形，有细鳞，两眼都在右侧。生活在浅海中，左侧向下卧在沙底。\n鲽zhá 1.见\"魻鲽\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲽"},{"id":"glyph-seal-9cca","script":"seal","character":"鳊","reading":"biān","description":"鱼名\n鳊biān 1.鱼名。鳊鱼。古亦称鲂。鱼纲鲤科。身体侧扁，头小而尖，鳞较细。生活在淡水中。肉味鲜美。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳊"},{"id":"glyph-seal-9cce","script":"seal","character":"鳎","reading":"tǎ","description":"鳎鱼\n鳎tǎ鳎目鱼，体侧扁似舌头。头小，两眼都在身体右侧。常侧卧在海底泥沙中。有卵～、条～等多种。可供食用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳎"},{"id":"glyph-seal-9ccf","script":"seal","character":"鳏","reading":"guān","description":"鱼名,即鲩鲲。又名鳡鱼\n死了妻子又未再结婚的男人\n鳏夫\n鳏guān老而无妻或丧妻的男人～夫。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳏"},{"id":"glyph-seal-9cd0","script":"seal","character":"鳐","reading":"yáo","description":"鳐鱼\n鳐yáo鳐鱼，体扁平，略呈圆形或菱形，尾细长。种类很多。某些类鳐鱼有一对能发电的器官。生活在海中。肉可食，肝可制鱼肝油。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳐"},{"id":"glyph-seal-9cd7","script":"seal","character":"鳗","reading":"mán","description":"鳗鱼,今俗曰鳗鲡\n鳗;海鳗\n海洋中，也供食用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳗"},{"id":"glyph-seal-9cd9","script":"seal","character":"鳙","reading":"yōng","description":"鱼名,鳙鱼,又名胖头鱼”、花鲢”、黑鲢”\n鳙yōng鱼名。鳙鱼也叫\"花鲢\"、\"胖头鱼\"。鳙鱼，头大，体侧扁，鳞细，生活在淡水中，供食用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳙"},{"id":"glyph-seal-9cdc","script":"seal","character":"鳜","reading":"guì","description":"即鳜鱼\n背隆起,口大,下颌突出,背鳍一个,鳞细小、圆形,性凶猛,捕食水中鱼虾\n鳜鯾\n鳜guì鳜鱼，也作\"桂鱼\"。体侧扁，青黄色，有黑色斑点。背隆起。口大鳞细，喜食鱼、虾。它是我国名贵淡水鱼之一。\n鳜jué 1.见\"鳜鯾\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳜"},{"id":"glyph-seal-9cde","script":"seal","character":"鳞","reading":"lín","description":"鳞片状物\n动物学名词。为被覆在动物体表的硬质小形薄片,是一种多样性的\n⒈鱼类、爬行动物和少数哺乳动物等体表上的角质或骨质的小薄片鱼～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳞"},{"id":"glyph-seal-9cdf","script":"seal","character":"鳟","reading":"zūn","description":"鳟鱼\n鳟zūn 1.赤眼鳟。亦名红眼鱼。鱼纲鲤科。体延长，前部圆筒形，后部侧扁，银灰色，眼上缘红色，每鳞片后具一小黑斑，尾鳍叉形。为生活于淡水中的常见食用鱼类，可供养\n殖。 2.虹鳟。鱼纲鲑科。体延长，侧扁，长约三十厘米。色鲜艳，背面和鳍暗绿色或褐色，有小黑斑，中央有一红色纵带。原产美国，后移殖于我国东北及朝鲜﹑日本与欧洲\n各国。生活在河流湖泊中。\n鳟zùn 1.赤眼鳟。亦名红眼鱼。鱼纲鲤科。体延长，前部圆筒形，后部侧扁，银灰色，眼上缘红色，每鳞片后具一小黑斑，尾鳍叉形。为生活于淡水中的常见食用鱼类，可供养\n殖。 2.虹鳟。鱼纲鲑科。体延长，侧扁，长约三十厘米。色鲜艳，背面和鳍暗绿色或褐色，有小黑斑，中央有一红色纵带。原产美国，后移殖于我国东北及朝鲜﹑日本与欧洲\n各国。生活在河流湖泊中。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳟"},{"id":"glyph-seal-9ce2","script":"seal","character":"鳢","reading":"lǐ","description":"鳢鱼\n一种淡水鱼,体圆长,口大,牙尖,色黑,有斑点,性凶猛,捕食其他鱼类。肉肥美,供食用。又名黑鱼、乌鳢、铜鱼,俗称乌鱼”\n鳢lǐ鱼名。乌鳢又叫\"乌鱼\"、\"黑鱼\"。头扁，体圆筒形，背鳍和臀鳍很长，生活在淡水中，捕食小鱼、蛙等。可养殖，供食用。但性凶猛，桅其它鱼类。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳢"},{"id":"glyph-seal-9e1f","script":"seal","character":"鸟","reading":"niǎo","description":"⒈脊椎动物的一类。全身有羽毛，前肢变为翅，后肢能行走，用肺呼吸，温血卵生，能飞爱护～儿。千山～飞绝。也有因翅退化不能飞的，如鸵～。\n①从高处往下看登高～瞰河山。\n②事物的概括描写～瞰国际形势。\n鸟diǎo 1.人﹑畜的雄性生殖器。多用为詈词。\n鸟què 1.地名用字。参见\"鸾鸟\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸟"},{"id":"glyph-seal-9e20","script":"seal","character":"鸠","reading":"jiū","description":"鸠鸽科的鸟的泛称\n维鸠盈之。\n维鸠方之。\n一种行于沙中的运载工具\n⒈鸟名。形状像鸽。种类很多，常见的有斑～、山～等，均已少见，要保护，禁止猎杀。\n鸠zhì 1.解决。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸠"},{"id":"glyph-seal-9e21","script":"seal","character":"鸡","reading":"jī","description":"家禽，有多种品种，可供食用或产蛋；雄鸡常在清晨啼叫。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9e23","script":"seal","character":"鸣","reading":"míng","description":"泛指发声\n⒈禽兽或虫叫鸡～。鹿～。蝉～。\n⒉发响，使发响雷～。自～钟。～礼炮。\n⒊〈表〉感情，喊叫～谢。～不平。～冤叫屈。\n⒋表达意见、主张等百家争～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸣"},{"id":"glyph-seal-9e25","script":"seal","character":"鸥","reading":"ōu","description":"水鸟名","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸥"},{"id":"glyph-seal-9e28","script":"seal","character":"鸨","reading":"bǎo","description":"鸟名。头小颈长。鸨科中型和大型狩猎鸟类,与鹤形目的鹤和秧鸡有亲缘关系,比雁略大,背上有黄褐色和黑色斑纹,不善于飞,而善于走\n旧时的老妓女\n①鸟类的一属，不善飞，能涉水。\n②鸨母老～。\n【鸨儿】见【鸨母】。\n【鸨母】旧社会开设妓院的女人。又叫鸨儿、老鸨。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸨"},{"id":"glyph-seal-9e29","script":"seal","character":"鸩","reading":"zhèn","description":"传说中的一种毒鸟。把它的羽毛放在酒里，可以毒杀人。\n用鸩的羽毛泡成的毒酒～酒。饮～止渴。\n用毒酒害人。\n⒈传说中的一种毒鸟。羽毛紫绿色，放在酒中能毒死人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸩"},{"id":"glyph-seal-9e2a","script":"seal","character":"鸪","reading":"gū","description":"用于“鹧鸪”“鹁鸪”等鸟名。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9e2c","script":"seal","character":"鸬","reading":"lú","description":"用于“鸬鹚”，一种善于潜水捕鱼的水鸟。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9e2d","script":"seal","character":"鸭","reading":"yā","description":"水禽名。俗称鸭子\n对其妻有外遇者的称呼\n鸭yā水鸟名。分家～和野～，嘴扁，颈长，脚短，趾间有蹼，善游泳。野鸭会飞。通常指家鸭，不能高飞，可成群饲养，肉、卵供食用，鸭绒供做衣、被等。已有人工饲养野～","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸭"},{"id":"glyph-seal-9e2e","script":"seal","character":"鸮","reading":"xiāo","description":"鸮形目鸟类的统称，包括多种猫头鹰。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9e2f","script":"seal","character":"鸯","reading":"yāng","description":"见“鸳鸯”，一种水鸟；“鸯”在传统称谓中指雌鸟。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9e31","script":"seal","character":"鸱","reading":"chī","description":"猫头鹰一类的鸟。又名鴞角鸱、怪鸱、鸺鸱\n用皮革制作的酒囊。鸱夷”的略称\n鸱吻\n鸱鸮,鸱枭\n⒈一种凶猛的鸟，又叫\"鹞鹰\"，已少见， 要保护，禁止猎杀。\n①〈古〉指鹪鹩，一种小鸟。\n②猫头鹰一类的鸟。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸱"},{"id":"glyph-seal-9e32","script":"seal","character":"鸲","reading":"qú","description":"鸲属鸟\n鸲gōu 1.见\"鸲鹠\"。\n鸲gòu 1.雉鸣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸲"},{"id":"glyph-seal-9e33","script":"seal","character":"鸳","reading":"yuān","description":"比喻同事,同僚","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸳"},{"id":"glyph-seal-9e37","script":"seal","character":"鸷","reading":"zhì","description":"凶猛;残暴\n猱进鸷击。\n鸷zhé 1.击搏。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸷"},{"id":"glyph-seal-9e39","script":"seal","character":"鸹","reading":"guā","description":"乌鸦的俗称,如老鸹\n鸹guā乌鸦。俗称\"老鸹\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸹"},{"id":"glyph-seal-9e3d","script":"seal","character":"鸽","reading":"gē","description":"鸽派\n他们是国会中鸽派代表,常常反对鹰派的冷战主张\n鸽哨\n空中划过一串清脆的鸽哨声\n鸽子","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸽"},{"id":"glyph-seal-9e3e","script":"seal","character":"鸾","reading":"luán","description":"赤色,五采,鸡形,鸣中五音。\n鸾guàn 1.地名用字。参见\"鸾鸟\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸾"},{"id":"glyph-seal-9e3f","script":"seal","character":"鸿","reading":"hóng","description":"鹄。即天鹅\n喻指\n⒈大型雁类的泛称。\n⒊大～文。～图。\n鸿hòng 1.见\"鸿絧\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸿"},{"id":"glyph-seal-9e44","script":"seal","character":"鹄","reading":"hú；gu","description":"箭靶的中心\n目标,目的\n通鹤”。鸟名∽科各种禽类的泛称\n脱笼\n⒈箭靶子。\n⒉见hú、hè。\n鸿～之志哉。\n⒉见gǔ。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹄"},{"id":"glyph-seal-9e45","script":"seal","character":"鹅","reading":"é","description":"鹅 é家禽。像鸭但比鸭大，颈长，喙扁阔，脚有蹼。羽毛白色或灰色，额部有橙黄色或黑褐色肉质突起，雄的突起较大。能游泳，吃谷物、蔬菜、鱼虾等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹅"},{"id":"glyph-seal-9e46","script":"seal","character":"鹆","reading":"yù","description":"鸟名。鸲鹆。又叫八哥儿”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹆"},{"id":"glyph-seal-9e47","script":"seal","character":"鹇","reading":"xián","description":"用于“白鹇”，一种雉类，雄鸟背部和尾羽以白色为主。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9e48","script":"seal","character":"鹈","reading":"tí","description":"用于“鹈鹕”，一种大型水鸟，喙长，喙下有喉囊。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9e4f","script":"seal","character":"鹏","reading":"péng","description":"比喻前程远大\n雄伟,伟大\n⒈〈古〉传说中的一种大鸟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹏"},{"id":"glyph-seal-9e51","script":"seal","character":"鹑","reading":"chún","description":"鹌鹑的简称\n部为发红色的皮黄色,腹部呈白色\n赤凤\n星宿名。南方朱鸟七宿的总称\n喻衣服破烂的\n鹑 chún鹌鹑。\n【鹑衣百结】衣裳好像鹌鹑的羽毛，补丁压补丁。形容衣服破烂不堪。\n鹑tuán 1.即雕。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹑"},{"id":"glyph-seal-9e58","script":"seal","character":"鹘","reading":"gǔ","description":"鹘鸼,鹘鸠\n鸷鸟名。即隼\n山中栖鹘。\n鹘仑吞枣\n⒉见hú。\n⒈鸟名。一种小鸠。似山鹊而小,短尾,青黑色,多声。古书上说的一种鸟即\"隼\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹘"},{"id":"glyph-seal-9e5a","script":"seal","character":"鹚","reading":"cí","description":"鹚cí 1.见\"鸬鹚\"﹑\"鹚?\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹚"},{"id":"glyph-seal-9e5c","script":"seal","character":"鹜","reading":"wù","description":"家鸭\n奔驰。通鹜”\n引申为追\n鹜mù 1.家鸭。 2.晋以后亦指野鸭。 3.通\"骛\"。疾驰。 4.引申为追求。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹜"},{"id":"glyph-seal-9e5e","script":"seal","character":"鹞","reading":"yào","description":"雀鹰的俗称。古名鹬子”、笼脱”,今通称鹞鹰”、鹞子\n鹰科,鹞属各种鸟的通称\n鹞鹰\n鹞子\n猎杀。\n鹞yáo 1.见\"鹞雉\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹞"},{"id":"glyph-seal-9e64","script":"seal","character":"鹤","reading":"hè","description":",羽毛更紧密,部分秃顶,嘴较钝并在近中央处有较大鼻孔,后趾向上抬起\n比喻白色\n鹤hè鸟儿，要保护，禁止猎杀。它的头小，颈和脚细长，嘴长而直，翼大善飞，羽毛白色或灰色。常见的是白～，又叫\"仙～\"、\"丹顶～\"。羽毛白色，头顶红色，叫声高而清脆\n。捕食鱼、虾等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹤"},{"id":"glyph-seal-9e66","script":"seal","character":"鹦","reading":"yīng","description":"鸟名,鹦鹉。俗称鹦哥”\n鹦哥\n鹦鹉\n酒器名\n鹦鹉学舌\n要保护，禁止猎杀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹦"},{"id":"glyph-seal-9e67","script":"seal","character":"鹧","reading":"zhè","description":"捕食昆虫及蚯蚓等\n鹧zhè鸟名。鹧鸪，像鸭但较鸭小。羽毛头顶棕色，脚橙黄色，背和腹部多为黑白两色相杂。吃植物种子和昆虫、蚯蚓等。此鸟已少见，要保护，禁止猎杀食用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹧"},{"id":"glyph-seal-9e69","script":"seal","character":"鹩","reading":"liáo","description":"鹩哥","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹩"},{"id":"glyph-seal-9e6a","script":"seal","character":"鹪","reading":"jiāo","description":"用于“鹪鹩”，一种体形很小的鸟。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"}];
